package com.marketlabs.pulse.data.theme

// Generated by Claude Code.

import android.content.Context
import androidx.datastore.preferences.core.edit
import com.marketlabs.pulse.ui.theme.MarketPulseTheme
import dagger.hilt.android.qualifiers.ApplicationContext
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map
import javax.inject.Inject

class ThemeRepositoryImpl @Inject constructor(
    @ApplicationContext private val context: Context
) : ThemeRepository {

    override val selectedTheme: Flow<MarketPulseTheme> = context.themeDataStore.data.map { prefs ->
        val storedName = prefs[ThemePreferences.SELECTED_THEME]
        // A stored name that no longer matches an enum entry (e.g. a preset renamed/removed in a
        // future revision) falls back to the default rather than crashing on valueOf().
        storedName?.let { name -> runCatching { MarketPulseTheme.valueOf(name) }.getOrNull() }
            ?: DEFAULT_THEME
    }

    override suspend fun setTheme(theme: MarketPulseTheme) {
        context.themeDataStore.edit { prefs ->
            prefs[ThemePreferences.SELECTED_THEME] = theme.name
        }
    }

    companion object {
        /** LILAC — the developer's stated hero preset (Design Direction), used until the user ever picks one. */
        private val DEFAULT_THEME = MarketPulseTheme.LILAC
    }
}
